    for directory in std::env::split_paths(&path) {
        for name in ["python", "python3"] {
            assert!(!directory.join(name).is_file(), "Python on test PATH: {}", directory.display());
        }
    }
    assert!(coverage_fixture::a::value());
    assert!(coverage_fixture::b::value());
}
